<?php $pageTitle='Clinic Schedules'; include __DIR__.'/../includes/header.php'; require_login('administrator'); $rows=Database::connection()->query('SELECT cs.*, u.name doctor_name FROM clinic_schedule cs JOIN doctors d ON d.id=cs.doctor_id JOIN users u ON u.id=d.user_id')->fetchAll(); ?><h1>Clinic Schedules</h1><table class="table"><tr><th>Doctor</th><th>Day</th><th>Start</th><th>End</th></tr><?php foreach($rows as $r): ?><tr><td><?= e($r['doctor_name']) ?></td><td><?= e($r['day']) ?></td><td><?= e($r['start_time']) ?></td><td><?= e($r['end_time']) ?></td></tr><?php endforeach; ?></table><?php include __DIR__.'/../includes/footer.php'; ?>
